sys_ui_action.script:
function ValidateAssigned() {
    if (g_form.getValue('bulk_id.bulk_field_group') != '') {
        g_form.addErrorMessage("Please submit the task from Bulk Form");
        return false;
    }
    if (g_form.getValue('outcome') == '' && g_form.getValue('trade_task_type') == 'Maker') {
        g_form.setMandatory('outcome', true);
        g_form.clearMessages();
        g_form.addErrorMessage("Fill Outcome field before submitting the task");
        return false;
    }
    if (g_form.getValue('decision') == '' && g_form.getValue('trade_task_type') == 'Checker') {
        g_form.setMandatory('decision', true);
        g_form.clearMessages();
        g_form.addErrorMessage("Fill Decision field before submitting the task");
        return false;
    }
    if (!(g_form.mandatoryCheck()) || g_form.getValue('assigned_to') == '') {

        g_form.setMandatory('assigned_to', true);
        g_form.clearMessages();
        g_form.addErrorMessage("Fill Mandatory Fields or Assigned to field before submitting the task");
        return false;
    }
    var assigneeUser = g_user.userID;
    if (g_form.getValue('assigned_to') != assigneeUser) {

        if (assigneeUser == g_form.getValue('trade_case_id.current_maker_assignee')) {
            g_form.setValue('assigned_to', '');
            g_form.setMandatory('assigned_to', true);
            g_form.clearMessages();
            g_form.addErrorMessage("Checker cannot be the same user who actioned the maker task");
            return false;
        } else
            g_form.setValue('assigned_to', assigneeUser);
    }

    //block user if no fields are amended
    if ((g_form.getValue('state') == 2) && (g_form.getValue('trade_task_type') == 'Maker')) { //from work in progress to closed complete


        // clientDataVal will now be "myDataValue"
        var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
        eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
        eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
        eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
        eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_mss_c_proc_mss_custody_task');
        eligbleCheck.getXMLAnswer(checkIfFieldsModifiedForAmend);
    } else if (g_form.getValue('trade_task_type') == 'Checker') {
        gsftSubmit(null, g_form.getFormElement(), 'sysverb_insert_task'); // For Checker Task
    }

    function checkIfFieldsModifiedForAmend(check) {
        if (check.toString() == 'true') {

            var checkIfAmended = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
            checkIfAmended.addParam('sysparm_name', 'amendEvaluateIfAmended');
            checkIfAmended.addParam('sysparm_tradeID', g_form.getValue('trade_id'));
            checkIfAmended.addParam('sysparm_tasksecurityID', g_form.getDisplayBox('bulk_id.amend_security_id_sec_id_ref').value ? g_form.getDisplayBox('bulk_id.amend_security_id_sec_id_ref').value : g_form.getValue('bulk_id.security_id_sec_id'));
            checkIfAmended.addParam('sysparm_taskcounterParCode', g_form.getDisplayBox('bulk_id.amend_counterparty_code_ref').value ? g_form.getDisplayBox('bulk_id.amend_counterparty_code_ref').value : g_form.getValue('bulk_id.amend_counterparty_code'));
            checkIfAmended.addParam('sysparm_taskswitchAcc', g_form.getDisplayBox('bulk_id.amend_switch_account_ref').value ? g_form.getDisplayBox('bulk_id.amend_switch_account_ref').value : g_form.getValue('bulk_id.amend_switch_account'));
            checkIfAmended.addParam('sysparm_tasktradeDate ', g_form.getValue("bulk_id.amend_trade_date"));
            checkIfAmended.addParam('sysparm_tasksettlementDate', g_form.getValue("bulk_id.settlement_date"));
            checkIfAmended.addParam('sysparm_taskdealPrice ', g_form.getValue("bulk_id.amend_deal_price"));
            checkIfAmended.addParam('sysparm_taskdealCurrency', g_form.getValue("bulk_id.amend_deal_currency"));
            checkIfAmended.addParam('sysparm_tasksettlementCurrency', g_form.getValue("bulk_id.amend_settlement_currency"));
            checkIfAmended.addParam('sysparm_tasksettlementAmount', g_form.getValue("bulk_id.amend_settlement_amount"));
            checkIfAmended.addParam('sysparm_taskcounterPartyRef', g_form.getValue("bulk_id.counterparty_reference"));
            checkIfAmended.addParam('sysparm_taskcusRef', g_form.getValue("bulk_id.customer_reference"));
            checkIfAmended.addParam('sysparm_tasklocCode', g_form.getValue("bulk_id.amend_location_code"));
            checkIfAmended.addParam('sysparm_taskhmiIndicator', g_form.getValue("bulk_id.amend_hmi_indicator"));
            checkIfAmended.addParam('sysparm_taskscripholIndicator', g_form.getValue("bulk_id.amend_script_hold_indicator"));
            checkIfAmended.addParam('sysparm_taskcashHoldIndicator', g_form.getValue("bulk_id.amend_cash_hold_indicator"));
            checkIfAmended.addParam('sysparm_taskgdiIncidcator', g_form.getValue("bulk_id.amend_gdi_indicator"));
            checkIfAmended.addParam('sysparm_taskpayMethod', g_form.getValue("bulk_id.amend_payment_method"));
            checkIfAmended.addParam('sysparm_taskswitchIndicator', g_form.getValue("bulk_id.amend_switch_indicator"));
            checkIfAmended.addParam('sysparm_tasksusAccNum', g_form.getValue("bulk_id.amend_suspense_account_number"));
            checkIfAmended.addParam('sysparm_taskcounterSettAccNum', g_form.getValue("bulk_id.amend_counterparty_settlement_account_number"));
            checkIfAmended.addParam('sysparm_taskconverAccSwitch', g_form.getValue("bulk_id.amend_convert_to_account_switching"));
            checkIfAmended.addParam('sysparm_taskaccOfClient', g_form.getValue("bulk_id.amend_a_c_of_client"));
            checkIfAmended.addParam('sysparm_taskReceiverCusBic', g_form.getValue("bulk_id.amend_receiver_custodian_bic")); //Receiver Bic MSSCUSTODY-7158
            checkIfAmended.addParam('sysparm_taskDelivererCusBic', g_form.getValue("bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic")); //Deliverer Bic MSSCUSTODY-7158
            checkIfAmended.addParam('sysparm_taskBuyerBic', g_form.getValue("bulk_id.amend_buyer_bic")); //buyer Bic MSSCUSTODY-7158
            checkIfAmended.addParam('sysparm_taskSellerBic', g_form.getValue("bulk_id.amend_seller_bic_buyer_bic")); //seller Bic MSSCUSTODY-7158
            checkIfAmended.addParam('sysparm_taskplaceofSett', g_form.getValue("bulk_id.amend_place_of_settlement_bic"));
            checkIfAmended.addParam('sysparm_taskamendChargesType', g_form.getValue("bulk_id.amend_charges_type"));
            checkIfAmended.addParam('sysparm_taskamendChargesCCY', g_form.getValue("bulk_id.amend_charges_ccy"));
            checkIfAmended.addParam('sysparm_taskamendChargesAMT', g_form.getValue("bulk_id.amend_charges_amt"));
            checkIfAmended.addParam('sysparm_taskamendNSSC', g_form.getValue("bulk_id.amend_nssc"));

            checkIfAmended.addParam('sysparm_taskamendsipuposeCode', g_form.getValue("bulk_id.amend_si_purpose_code")); //MSSCUSTODY-7294
            checkIfAmended.addParam('sysparm_taskamendDataSourceScheme', g_form.getValue("bulk_id.amend_data_source_scheme")); //MSSCUSTODY-7294
            checkIfAmended.addParam('sysparm_taskamendPropriatyCode', g_form.getValue("bulk_id.amend_propriaty_code")); //MSSCUSTODY-7294
            checkIfAmended.addParam('sysparm_issind', g_form.getValue('bulk_id.amend_iss')); //MSSCUSTODY-7747
            checkIfAmended.addParam('sysparm_swh', g_form.getValue('bulk_id.amend_swh')); //MSSCUSTODY-7747
            checkIfAmended.addParam('sysparm_taskfa', g_form.getValue('bulk_id.amend_fa')); //MSSCUSTODY-8151
            checkIfAmended.addParam('sysparm_taskswitchReference', g_form.getDisplayBox('bulk_id.amend_switch_reference').value ? g_form.getDisplayBox('bulk_id.amend_switch_reference').value : g_form.getValue('bulk_id.amend_trade_switch_reference')); //MSSCUSTODY-7240
            checkIfAmended.getXMLAnswer(amendFlag);

        } else {
            //alert('Assigned to value 343 ' + g_form.getValue('assigned_to'));
            gsftSubmit(null, g_form.getFormElement(), 'sysverb_insert_task'); //for other outcomes
        }
    }

    function amendFlag(answer) {
        if (answer.toString() == 'false') { //Validate if the user has modified any value to proceed

            var amendNoChangeWarning = new GlideModal("glide_alert_standard", false, 600);
            amendNoChangeWarning.setTitle("Trade Amendment Instructions");
            amendNoChangeWarning.setPreference("title", "No changes observed, Click OK to continue updating");
            amendNoChangeWarning.setPreference("warning", "true");
            amendNoChangeWarning.render();

        } else {





            var gm = new GlideModal("glide_confirm_basic", true, 600);
            gm.setTitle("Confirmation");
            gm.setPreference("title", "Do you want to proceed submission for trade amendment?");
            gm.setPreference("onPromptComplete", function() {

                //Positive Loop

                var trdSettlementCurr = g_scratchpad.settlementCurrency;
                var trdSettlementDate = g_scratchpad.settlementDate;
                var tskAmendDate = g_form.getValue("bulk_id.amend_trade_date");
                var amendCurr = g_form.getValue("bulk_id.amend_settlement_currency");
                var amendSettAmt = g_form.getValue("bulk_id.amend_settlement_amount");
                var amendSettDate = g_form.getValue("bulk_id.settlement_date");
                var amendLocationCode = g_form.getValue("bulk_id.amend_location_code");
                var tradeId = g_form.getValue("trade_id");
                var gdiIndicator = g_form.getValue("bulk_id.amend_gdi_indicator");
                var placeOfSettlementBic = g_form.getValue("bulk_id.amend_place_of_settlement_bic");
                var amendScriptHoldIndicator = g_form.getValue("bulk_id.amend_script_hold_indicator");
                var amendDealPrice = g_form.getValue("bulk_id.amend_deal_price");
                var amendDealCurrency = g_form.getValue("bulk_id.amend_deal_currency");
                var trdCashAccId = g_form.getValue("trade_id.cash_account_id");
                var amendBuyerSellerBic = g_form.getValue("bulk_id.amend_seller_bic_buyer_bic");
                var amendCustomerReference = g_form.getValue("bulk_id.customer_reference");
                var amendCashHoldIndicator = g_form.getValue("bulk_id.amend_cash_hold_indicator");
                var amendSuspenseAccNum = g_form.getValue("bulk_id.amend_suspense_account_number");
                var amendChargesType = g_form.getValue("bulk_id.amend_charges_type");
                var amendChargesCcy = g_form.getValue("bulk_id.amend_charges_ccy");
                var amendChargesAmt = g_form.getValue("bulk_id.amend_charges_amt");
                var amendDelivererReceivererBic = g_form.getValue("bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic");
                var amendCounterpartySettAccNum = g_form.getValue("bulk_id.amend_counterparty_settlement_account_number");
                var accOfClient = g_form.getValue("bulk_id.amend_a_c_of_client");
                var amendCounterpartyRef = g_form.getValue("bulk_id.counterparty_reference");
                var amendSWH = g_form.getValue("bulk_id.amend_swh"); //7910
				var switchRef = g_form.getValue("bulk_id.amend_switch_reference"); //8173
				var tradeSwitchRef = g_form.getValue("bulk_id.amend_trade_switch_reference"); //8173
				var amendFA = g_form.getValue("bulk_id.amend_fa"); //8184

                var amendSecurityID = g_form.getDisplayBox('bulk_id.amend_security_id_sec_id_ref').value;
                var tradeAmendSecurityID = g_form.getValue('bulk_id.security_id_sec_id');
                var amendSwitchAccount = g_form.getDisplayBox('bulk_id.amend_switch_account_ref').value;
                var tradeAmendSwitchAccount = g_form.getValue('bulk_id.amend_switch_account');
                var amendCounterpartyCode = g_form.getDisplayBox('bulk_id.amend_counterparty_code_ref').value;
                var tradeAmendCounterpartyCode = g_form.getValue('bulk_id.amend_counterparty_code');
                var convertToAccSwitching = g_form.getValue("bulk_id.amend_convert_to_account_switching");
                // MSSCUSTODY-7295
                var amendSiPurposeCode = g_form.getValue("bulk_id.amend_si_purpose_code");
                var amendDataSourceScheme = g_form.getValue("bulk_id.amend_data_source_scheme");
                var amendPropriatyCode = g_form.getValue("bulk_id.amend_propriaty_code");
                // MSSCUSTODY-7133
                var amendBuyerBic = g_form.getValue("bulk_id.amend_buyer_bic");
                var amendReceivererBic = g_form.getValue("bulk_id.amend_receiver_custodian_bic");

                // MSSCUSTODY-6226
                var legacyStatus = g_form.getValue('trade_id.legacy_status');
                var legacySubStatus = g_form.getValue('trade_id.legacy_sub_status');
                var switchIndicator = g_form.getValue('bulk_id.amend_switch_indicator');
                var transactionType = g_form.getValue('trade_id.transaction_type');
                var owningBusiness = g_scratchpad.owningBus;

                var trdDetails = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
                trdDetails.addParam('sysparm_name', 'evalAmendInputs');
                trdDetails.addParam('sysparm_trdSettlementDate', trdSettlementDate);
                trdDetails.addParam('sysparm_taskAmendDate', tskAmendDate);
                trdDetails.addParam('sysparm_trdSettlementCurr', trdSettlementCurr);
                trdDetails.addParam('sysparm_taskAmendCurr', amendCurr);
                trdDetails.addParam('sysparm_taskAmendSettAmt', amendSettAmt);
                trdDetails.addParam('sysparm_amendSettDate', amendSettDate);
                trdDetails.addParam('sysparm_taskAmendLocationCode', amendLocationCode);
                trdDetails.addParam('sysparm_tradeId', tradeId);
                trdDetails.addParam('sysparm_gdiIndicator', gdiIndicator);
                trdDetails.addParam('sysparm_placeOfSettlementBic', placeOfSettlementBic);
                trdDetails.addParam('sysparm_amendScriptHoldIndicator', amendScriptHoldIndicator);
                trdDetails.addParam('sysparm_amendDealPrice', amendDealPrice);
                trdDetails.addParam('sysparm_amendDealCurrency', amendDealCurrency);
                trdDetails.addParam('sysparm_trdCashAccId', trdCashAccId);
                trdDetails.addParam('sysparm_amendBuyerSellerBic', amendBuyerSellerBic);
                trdDetails.addParam('sysparm_amendCustomerReference', amendCustomerReference);
                trdDetails.addParam('sysparm_amendCashHoldIndicator', amendCashHoldIndicator);
                trdDetails.addParam('sysparm_amendSuspenseAccNum', amendSuspenseAccNum); //to check
                trdDetails.addParam('sysparm_amendChargesType', amendChargesType);
                trdDetails.addParam('sysparm_amendChargesCcy', amendChargesCcy);
                trdDetails.addParam('sysparm_amendChargesAmt', amendChargesAmt);
                trdDetails.addParam('sysparm_amendDelivererReceivererBic', amendDelivererReceivererBic);
                trdDetails.addParam('sysparm_amendSwitchAccount', amendSwitchAccount);
                trdDetails.addParam('sysparm_amendSecurityID', amendSecurityID);
                trdDetails.addParam('sysparm_amendCounterpartyCode', amendCounterpartyCode);
                trdDetails.addParam('sysparm_accOfClient', accOfClient);
                trdDetails.addParam('sysparm_amendCounterpartySettAccNum', amendCounterpartySettAccNum);
                trdDetails.addParam('sysparm_amendCounterpartyRef', amendCounterpartyRef);
                trdDetails.addParam('sysparm_legacyStatus', legacyStatus);
                trdDetails.addParam('sysparm_legacySubStatus', legacySubStatus);
                trdDetails.addParam('sysparm_switchIndicator', switchIndicator);
                trdDetails.addParam('sysparm_owningBusiness', owningBusiness);
                trdDetails.addParam('sysparm_convertToAccSwitching', convertToAccSwitching);
                trdDetails.addParam('sysparm_transactionType', transactionType);
                // MSSCUSTODY-7295
                trdDetails.addParam('sysparm_amendSiPurposeCode', amendSiPurposeCode);
                trdDetails.addParam('sysparm_amendDataSourceScheme', amendDataSourceScheme);
                trdDetails.addParam('sysparm_amendPropriatyCode', amendPropriatyCode);

                trdDetails.addParam('sysparm_amendBuyerBic', amendBuyerBic); //7133
                trdDetails.addParam('sysparm_amendReceivererBic', amendReceivererBic); //7133

                trdDetails.addParam('sysparm_tradeAmendSecurityID', tradeAmendSecurityID);
                trdDetails.addParam('sysparm_tradeAmendSwitchAccount', tradeAmendSwitchAccount);
                trdDetails.addParam('sysparm_tradeAmendCounterpartyCode', tradeAmendCounterpartyCode);

                trdDetails.addParam('sysparm_amendSWH', amendSWH); //7910
				trdDetails.addParam('sysparm_switchRef', switchRef);  //8173
				trdDetails.addParam('sysparm_tradeSwitchRef', tradeSwitchRef);  //8173
				trdDetails.addParam('sysparm_amendFA', amendFA);  //8184
                trdDetails.getXMLAnswer(handleResponse);
            });
            gm.setPreference("onPromptCancel", function() {

                /* Commenting the cancelling logic as per enhancement story MSSCUSTODY-6679
                //Cancel the case and task and add comment
                var cancelCaseTask = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
                cancelCaseTask.addParam('sysparm_name', 'cancelCaseandTaskUserCancellation');
                cancelCaseTask.addParam('sysparm_caseID', g_form.getValue('trade_case_id'));
                cancelCaseTask.addParam('sysparm_taskID', g_form.getUniqueValue());
                cancelCaseTask.getXMLAnswer(cancelResponse);

                function cancelResponse() { //if user cancels trade amendment redirecting user to the trade page which is the previous screen
                    var redirectURL = '/x_hsb11_mss_c_proc_mss_custody_trade.do?sys_id=' + g_form.getValue('trade_id') + '&sysparm_view='; //url to redirect; this approach works in platform and Service Portal view
                    top.window.location = redirectURL;
                }
                //Cancel the case and task and add comment

                return false;
				*/
            });
            gm.render();

        }
    }




}


function handleResponse(response) {

    if (response.length > 98) { //to limit if there are any warnings
        g_form.clearMessages();
        g_form.addErrorMessage(response);
        return false;
        //g_scratchpad.amenEligibility = false;
    } else {
        //g_scratchpad.amenEligibility = true;

        //handling bulk creation if the validation is passed
        /*Artifacts involved: 
		MSSCUSTODY-5197
		1) Client Script - MSS Task Prepopulate Amend from Trade - To pass Trade ID and Set values for Field
		2) Script Include - MSSCustodyAmendUtils Method - getTradeFieldvalues - To retrive Values from trade and send back to client
		3) Client Script - MSS Task Create Bulk for Amend - To pass values from bulk extended fields and send to below script inlcude to create bulk record
		4) Script Include - MSSAmendUtilsCore - Create bulk record and map to the task
		This method is to prepropulate the amend fields for automated task when the outcome is selected as Amend related outcomes
   		 Once the form is submitted, this method executes and populates thefield values from the trade
		*/

        /*
        Eligibility Check Artifacts: 
        Script Include : x_hsb11_mss_c_proc.MSSCustodyAmendUtils - evalAmendEligibility
        System Property: x_hsb11_mss_c_proc.enableautomatedamend.market - Only available markets will allow this script to execute
        System Property: x_hsb11_mss_c_proc.enableautomatedamend.outcomes - Only available markets will allow this script to execute
        */
        if ((g_form.getValue('state') == 2) && (g_form.getValue('trade_task_type') == 'Maker')) { //from work in progress to closed complete 1st Maker
            //handling the remote table fields
            var securityID = g_form.getDisplayBox('bulk_id.amend_security_id_sec_id_ref').value ? g_form.getDisplayBox('bulk_id.amend_security_id_sec_id_ref').value : g_form.getValue('bulk_id.security_id_sec_id');
            var counterParCode = g_form.getDisplayBox('bulk_id.amend_counterparty_code_ref').value ? g_form.getDisplayBox('bulk_id.amend_counterparty_code_ref').value : g_form.getValue('bulk_id.amend_counterparty_code');
            var switchAcc = g_form.getDisplayBox('bulk_id.amend_switch_account_ref').value ? g_form.getDisplayBox('bulk_id.amend_switch_account_ref').value : g_form.getValue('bulk_id.amend_switch_account');
            //handling the remote table fields

            var tradeDate = g_form.getValue("bulk_id.amend_trade_date");
            var settlementDate = g_form.getValue("bulk_id.settlement_date");
            var dealPrice = g_form.getValue("bulk_id.amend_deal_price");
            var dealCurrency = g_form.getValue("bulk_id.amend_deal_currency");
            var settlementCurrency = g_form.getValue("bulk_id.amend_settlement_currency");
            var settlementAmount = g_form.getValue("bulk_id.amend_settlement_amount");
            var counterPartyRef = g_form.getValue("bulk_id.counterparty_reference");
            var cusRef = g_form.getValue("bulk_id.customer_reference");
            var locCode = g_form.getValue("bulk_id.amend_location_code");
            var hmiIndicator = g_form.getValue("bulk_id.amend_hmi_indicator");
            var scripholIndicator = g_form.getValue("bulk_id.amend_script_hold_indicator");
            var cashHoldIndicator = g_form.getValue("bulk_id.amend_cash_hold_indicator");
            var gdiIncidcator = g_form.getValue("bulk_id.amend_gdi_indicator");
            var payMethod = g_form.getValue("bulk_id.amend_payment_method");
            var switchIndicator = g_form.getValue("bulk_id.amend_switch_indicator");
            var susAccNum = g_form.getValue("bulk_id.amend_suspense_account_number");
            var counterSettAccNum = g_form.getValue("bulk_id.amend_counterparty_settlement_account_number");
            var converAccSwitch = g_form.getValue("bulk_id.amend_convert_to_account_switching");
            var accOfClient = g_form.getValue("bulk_id.amend_a_c_of_client");
            var receiverBic = g_form.getValue("bulk_id.amend_receiver_custodian_bic"); //Receiver Bic MSSCUSTODY-7158
            var deliverBic = g_form.getValue("bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic"); //Deliverer Bic MSSCUSTODY-7158
            var buyerBic = g_form.getValue("bulk_id.amend_buyer_bic"); //buyer Bic MSSCUSTODY-7158
            var sellerBic = g_form.getValue("bulk_id.amend_seller_bic_buyer_bic"); //seller Bic MSSCUSTODY-7158
            var placeofSett = g_form.getValue("bulk_id.amend_place_of_settlement_bic");
            var amendChargesType = g_form.getValue("bulk_id.amend_charges_type");
            var amendChargesCCY = g_form.getValue("bulk_id.amend_charges_ccy");
            var amendChargesAMT = g_form.getValue("bulk_id.amend_charges_amt");
            var amendNSSC = g_form.getValue("bulk_id.amend_nssc");

            var amendsiPuposeCode = g_form.getValue("bulk_id.amend_si_purpose_code"); //MSSCUSTODY-7294
            var amendDataSourceScheme = g_form.getValue("bulk_id.amend_data_source_scheme"); //MSSCUSTODY-7294
            var amendPropriatryCode = g_form.getValue("bulk_id.amend_propriaty_code"); //MSSCUSTODY-7294
            var amendIssInd = g_form.getValue('bulk_id.amend_iss'); //MSSCUSTODY-7747
            var amendSwh = g_form.getValue('bulk_id.amend_swh'); //MSSCUSTODY-7515
            var amendFa = g_form.getValue('bulk_id.amend_fa'); //MSSCUSTODY-8151
            var amendSwitchRef = g_form.getValue('bulk_id.amend_switch_reference'); //MSSCUSTODY-7240





            var createBulk = new GlideAjax('x_hsb11_hsbc_mss_o.MSSAmendUtilsCore');
            createBulk.addParam('sysparm_name', "createBulkRecordForTradeAmend");
            createBulk.addParam('sysparm_taskSysID', g_form.getUniqueValue()); // Task number sent to update the bulk record
            createBulk.addParam('sysparm_assignmnetGrp', g_form.getValue('assignment_group'));
            createBulk.addParam('sysparm_assignedTo', g_form.getValue('assigned_to'));
            createBulk.addParam('sysparm_tradeID', g_form.getValue('trade_id'));
            createBulk.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
            createBulk.addParam('sysparm_bulkID', g_form.getValue('bulk_id'));
            //Amend Inputs
            createBulk.addParam('sysparm_securityID ', securityID);
            createBulk.addParam('sysparm_tradeDate', tradeDate);
            createBulk.addParam('sysparm_settlementDate', settlementDate);
            createBulk.addParam('sysparm_dealPrice', dealPrice);
            createBulk.addParam('sysparm_dealCurrency', dealCurrency);
            createBulk.addParam('sysparm_settlementCurrency', settlementCurrency);
            createBulk.addParam('sysparm_settlementAmount', settlementAmount);
            createBulk.addParam('sysparm_counterPartyRef', counterPartyRef);
            createBulk.addParam('sysparm_cusRef', cusRef);
            createBulk.addParam('sysparm_locCode', locCode);
            createBulk.addParam('sysparm_hmiIndicator', hmiIndicator);
            createBulk.addParam('sysparm_scripholIndicator', scripholIndicator);
            createBulk.addParam('sysparm_cashHoldIndicator', cashHoldIndicator);
            createBulk.addParam('sysparm_gdiIncidcator', gdiIncidcator);
            createBulk.addParam('sysparm_payMethod', payMethod);
            createBulk.addParam('sysparm_switchIndicator', switchIndicator);
            createBulk.addParam('sysparm_switchAcc', switchAcc);
            createBulk.addParam('sysparm_susAccNum', susAccNum);
            createBulk.addParam('sysparm_counterParCode', counterParCode);
            createBulk.addParam('sysparm_counterSettAccNum', counterSettAccNum);
            createBulk.addParam('sysparm_converAccSwitch', converAccSwitch);
            createBulk.addParam('sysparm_accOfClient', accOfClient);

            createBulk.addParam('sysparm_receiverBic', receiverBic); //Receiver Bic MSSCUSTODY-7158
            createBulk.addParam('sysparm_deliverBic', deliverBic); //Deliverer Bic MSSCUSTODY-7158
            createBulk.addParam('sysparm_buyerBic', buyerBic); //buyer Bic MSSCUSTODY-7158
            createBulk.addParam('sysparm_sellerBic', sellerBic); //seller Bic MSSCUSTODY-7158

            createBulk.addParam('sysparm_placeofSett', placeofSett);
            createBulk.addParam('sysparm_amendChargesType', amendChargesType);
            createBulk.addParam('sysparm_amendChargesCCY', amendChargesCCY);
            createBulk.addParam('sysparm_amendChargesAMT', amendChargesAMT);
            createBulk.addParam('sysparm_amendNSSC', amendNSSC);
            //Amend Inputs
            createBulk.addParam('sysparm_amendsiPuposeCode', amendsiPuposeCode); //MSSCUSTODY-7294
            createBulk.addParam('sysparm_amendDataSourceScheme', amendDataSourceScheme); //MSSCUSTODY-7294
            createBulk.addParam('sysparm_amendPropriatryCode', amendPropriatryCode); //MSSCUSTODY-7294
            createBulk.addParam('sysparm_amendIndIss', amendIssInd); //MSSCUSTODY-7747
            createBulk.addParam('sysparm_amendSwh', amendSwh); //MSSCUSTODY-7515
            createBulk.addParam('sysparm_amendfa', amendFa); //MSSCUSTODY-8151
            createBulk.addParam('sysparm_amendSwitchRef', g_form.getDisplayBox('bulk_id.amend_switch_reference').value ? g_form.getDisplayBox('bulk_id.amend_switch_reference').value : g_form.getValue('bulk_id.amend_trade_switch_reference')); //MSSCUSTODY-7240


            createBulk.getXMLAnswer(bulkCreation);
        }



        ////handling bulk creation if the validation is passed
        gsftSubmit(null, g_form.getFormElement(), 'sysverb_insert_task');
    }

    function bulkCreation(resposne) {
        g_form.setValue("comments", 'Bulk Record created and associated to the task for Trade Amendment');
    }
}


if (typeof window == 'undefined') {

    current.assigned_to = gs.getUserID();
    //new 4112
    // MSSCUSTODY-3964 - Canceling associated flow if outcome is Review and Close the task for automated
    if (current.outcome == 'Review and closed the task') {
        current.state = 3; //Closed complete
        var flowContextCancel = new HSBCTradeTaskUtils();
        flowContextCancel.cancelFlow(current.trade_case_id, 'Cancelling in-progress flows as outcome is Review and Closed the task');
        current.work_notes = 'Cancelling in-progress flows as outcome is Review and Closed the task';
    }
    current.state = 3; //Closed complete.
    //Set state as 'Awaiting info' for Amend trade Outcome on Submit
    if (current.outcome == 'Amend Trade') {
        //current.state = 6;
        current.work_notes = "GHSS amendment is in progress. Awaiting response from RPA";
        current.outbound_created = true;
    }


    if (current.trade_task_type == 'Checker' && current.decision == 'Reject and create a new task') {
        current.sub_trade_task_type = 'Checker-Rejected';
    }

    //code to traverse the next unassigned record
    var gURI = new GlideURI();
    var list_query = gURI.get('sysparm_record_list');
    //gs.info('filtered list '+ list_query );

    var number_rows = gURI.get('sysparm_record_rows');
    //	gs.info('rows ' + number_rows);
    var host = gs.getProperty("glide.servlet.uri");
    var user = gs.getUserID();
    //gs.info('Assigned to value 380 ' + g_form.getValue('assigned_to') + 'current' + current.assigned_to);
    current.update();

    var si = new open_new_task().opentask1(list_query, user);
    //   gs.info('sysid '+si);

    si1 = si.split('&');
    si2 = si1[1].toString();
    si3 = si1[0].toString();
    // end of code for traversing.
    //	gs.info ('si= '+si +' si1 = '+si1 +" si2= "+ si2 +' si3=' +si3);

    if ((si2 != 'undefined') && (si3 == 'task')) {
        //		gs.info('inside task');
        action.setRedirectURL(host + "x_hsb11_mss_c_proc_mss_custody_task.do?sys_id=" + si2 + "&sysparm_record_target=x_hsb11_mss_c_proc_mss_custody_task&sysparm_record_row=2&sysparm_record_rows=" + number_rows + "&sysparm_record_list=" + list_query); //redirection to next unassigned record
    }
    if (si3 == 'trade') {
        //		gs.info('inside trade');
        action.setRedirectURL(host + "x_hsb11_mss_c_proc_mss_custody_trade.do?sys_id=" + si2);
    }
    if (si2 == 'undefined') {
        //	gs.info(' undefined');
        action.setRedirectURL(host + 'x_hsb11_mss_c_proc_mss_custody_task_list.do?sysparm_query=' + list_query);
    }

}
